import 'package:dio/dio.dart';
import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:get_it/get_it.dart';
import 'package:hive_ce_flutter/hive_ce_flutter.dart';

import '../../features/account/account_injection.dart';
import '../../features/auth/auth_injection.dart';
import '../../features/capture/capture_injection.dart';
import '../../features/entries/entries_injection.dart';
import '../../features/vault/vault_injection.dart';
import '../network/access_token_provider.dart';
import '../network/api_client.dart';
import '../network/header_interceptor.dart';
import '../network/retry_interceptor.dart';
import '../network/url_builder.dart';
import '../session/session_expiry_notifier.dart';

/// The project's single `get_it` instance — exactly one DI container exists
/// (architecture spine). Every feature's `registerXFeature()` registers
/// through this same `sl`, never a second container.
final sl = GetIt.instance;

/// Bootstraps core infrastructure: loads `.env`, then registers
/// `FlutterSecureStorage`, `Dio` (configured with the header + retry
/// interceptors) and `ApiClient` through `sl` — the `dio` +
/// `flutter_secure_storage` + `get_it` integration spike this story proves
/// before anything else is built on top of it.
Future<void> setupCoreDependencies() async {
  await dotenv.load(fileName: '.env');

  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');

  sl.registerLazySingleton<FlutterSecureStorage>(
    () => const FlutterSecureStorage(),
  );

  sl.registerLazySingleton<AccessTokenProvider>(
    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
  );

  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));

  // Story 1.5 — `dispose:` wires `SessionExpiryNotifier.dispose()` into
  // `get_it`'s own reset lifecycle, same rationale as `SessionRepository`'s
  // own registration below. Registration order here is cosmetic, not
  // load-bearing: `registerLazySingleton` only builds its instance on first
  // `sl<T>()` access, so `ApiClient`'s factory can resolve this dependency
  // correctly regardless of which of the two is registered first.
  sl.registerLazySingleton<SessionExpiryNotifier>(
    () => SessionExpiryNotifierImpl(),
    dispose: (notifier) => notifier.dispose(),
  );

  sl.registerLazySingleton<Dio>(() {
    final dio = Dio(
      BaseOptions(
        // Design note (docs/input is silent on exact numbers): a stalled
        // connection must still fail instead of hanging indefinitely.
        connectTimeout: const Duration(seconds: 10),
        receiveTimeout: const Duration(seconds: 30),
        sendTimeout: const Duration(seconds: 30),
      ),
    );
    dio.interceptors.add(
      HeaderInterceptor(
        anonKey: supabaseAnonKey,
        accessTokenProvider: sl<AccessTokenProvider>(),
      ),
    );
    dio.interceptors.add(RetryInterceptor(dio));
    return dio;
  });

  sl.registerLazySingleton<ApiClient>(
    () => ApiClient(
      dio: sl<Dio>(),
      urlBuilder: sl<UrlBuilder>(),
      sessionExpiryNotifier: sl<SessionExpiryNotifier>(),
    ),
  );

  registerAuthFeature();
  registerVaultFeature();
  registerAccountFeature();

  // Story 3.1 — the app's first `hive_ce` usage: `initFlutter()` must
  // complete before `registerEntriesFeature()` opens its box (Code Map).
  await Hive.initFlutter();
  await registerEntriesFeature();
  registerCaptureFeature();
}

/// Test/teardown helper — resets the single `get_it` instance so each test
/// bootstraps its own clean registrations.
Future<void> resetCoreDependencies() => sl.reset();

/// A finished microphone recording — the on-disk file [path] plus its
/// [durationSeconds], known only once [MicRecorder.stop] returns. Plain
/// Dart, not `package:record`'s own types — keeps this port, and every
/// caller that depends on it (`AudioEntryCubit`), decoupled from that
/// package's shape (Boundaries: "decouple the cubit from both packages").
class MicRecording {
  const MicRecording({required this.path, required this.durationSeconds});

  final String path;
  final int durationSeconds;
}

/// Capture's own mic-recording port — the `record`-backed
/// `RecordMicRecorder` is the only implementation (Code Map), mirroring
/// `EntriesRepository`'s port convention (an abstract class in `domain/`,
/// a concrete `data/` class wrapping the real package, injected via
/// `capture_injection.dart`). `AudioEntryCubit` depends on this interface
/// only, never on `package:record` directly (RNF06-style boundary,
/// extended here to any native package, not just `data/`).
abstract class MicRecorder {
  /// Checks (and, per `record`'s own `AudioRecorder.hasPermission()`
  /// default, requests if not yet granted) microphone permission — the
  /// one permission check this story ever performs (Boundaries: "no
  /// separate `permission_handler`"). `false` means denied/unavailable.
  Future<bool> hasPermission();

  /// Starts a new recording session to a fresh temp file. Callers must
  /// have already confirmed [hasPermission] returns `true` — this method
  /// itself doesn't re-check.
  Future<void> start();

  /// Stops the current recording session, returning its file path and
  /// duration (whole seconds). `null` if no session was in progress.
  Future<MicRecording?> stop();

  /// Stops and discards (deletes) the current recording session, if any —
  /// used only when leaving the Áudio tab mid-recording (I/O matrix:
  /// "Recorder stopped/released", resource safety only, never the full
  /// Story 3.4 cross-tab cancel choreography).
  Future<void> cancel();

  /// A normalized (0.0–1.0) amplitude sample roughly every 200ms while a
  /// recording session is active — drives the waveform animation. No
  /// guaranteed emissions outside an active session.
  Stream<double> get amplitudeStream;
}

/// Capture's on-device speech-to-text port — the `whisper_ggml`-backed
/// `WhisperAudioTranscriber` is the only implementation (Code Map),
/// mirroring [MicRecorder]'s same port convention.
abstract class AudioTranscriber {
  /// Transcribes the audio file at [audioPath] entirely on-device
  /// (FR-12) — never sends audio bytes anywhere. `null` means failure (a
  /// local-only outcome, never wrapped in `Failure` — RNF09 scopes
  /// `Failure` to repository/backend calls); a non-null result is the
  /// transcribed text, which may itself be empty if nothing was said.
  Future<String?> transcribe(String audioPath);
}

